/**
 * The Markdown subset the Office tools accept, parsed into document blocks.
 *
 * The model already writes Markdown; teaching it a bespoke JSON schema for
 * Word would be a second syntax to get wrong. This parser deliberately covers
 * the constructs that make a useful document — headings, paragraphs, bullet and
 * numbered lists, tables, fenced code, quotes, bold/italic/code spans — and
 * ignores everything else rather than failing the whole document.
 *
 * Pure functions, no I/O: the same blocks feed the docx writer and the tests.
 */

/** One inline span with the formatting Word can carry. */
export class Run {
	constructor(text, bold = false, italic = false, code = false) {
		this.text = text;
		this.bold = bold;
		this.italic = italic;
		this.code = code;
	}
}

/** One top-level document block. */
export class Block {
	constructor(type, options = {}) {
		this.type = type;
		this.level = options.level ?? 0;
		this.runs = options.runs ?? [];
		this.rows = options.rows ?? [];
		this.lines = options.lines ?? [];
		this.quote = options.quote ?? false;
	}

	/** Plain text of a text-bearing block, for length caps and summaries. */
	plainText() {
		if (this.type === "table") return this.rows.map((row) => row.join(" ")).join("\n");
		if (this.type === "code") return this.lines.join("\n");
		return this.runs.map((run) => run.text).join("");
	}
}

/** True for the `| --- | :---: |` line that turns the previous row into a table. */
export function isTableSeparator(line) {
	const text = line.trim();
	if (!/^[|\s:-]+$/.test(text) || !text.includes("-")) return false;
	const cells = text.split("|").map((cell) => cell.trim()).filter((cell) => cell.length > 0);
	return cells.length > 0 && cells.every((cell) => /^:?-{2,}:?$/.test(cell));
}

/** Split a table row on unescaped pipes; trims cells and unescapes `\|`. */
export function splitTableRow(line) {
	let text = line.trim();
	if (text.startsWith("|")) text = text.slice(1);
	if (text.endsWith("|")) text = text.slice(0, -1);
	const cells = [];
	let current = "";
	for (let index = 0; index < text.length; index++) {
		const char = text[index];
		if (char === "\\" && text[index + 1] === "|") {
			current += "|";
			index++;
			continue;
		}
		if (char === "|") {
			cells.push(current.trim());
			current = "";
			continue;
		}
		current += char;
	}
	cells.push(current.trim());
	return cells;
}

/**
 * Parse inline formatting into runs.
 *
 * Not CommonMark: `*` inside a word is literal, unmatched markers stay text,
 * and nesting is limited to code > bold > italic. That is intentional — the
 * model is told the subset, and a half-understood emphasis must never lose the
 * text it wrapped.
 */
export function parseInline(text) {
	const runs = [];
	let plain = "";
	const flush = () => {
		if (plain.length > 0) {
			runs.push(new Run(plain));
			plain = "";
		}
	};
	for (let index = 0; index < text.length; index++) {
		const char = text[index];
		if (char === "\\" && index + 1 < text.length) {
			plain += text[index + 1];
			index++;
			continue;
		}
		if (char === "`") {
			const end = text.indexOf("`", index + 1);
			if (end > index + 1) {
				flush();
				runs.push(new Run(text.slice(index + 1, end), false, false, true));
				index = end;
				continue;
			}
		}
		if (char === "*" && text[index + 1] === "*") {
			const end = text.indexOf("**", index + 2);
			if (end > index + 2) {
				flush();
				runs.push(new Run(text.slice(index + 2, end), true, false, false));
				index = end + 1;
				continue;
			}
		}
		if (char === "_" && text[index + 1] === "_") {
			const end = text.indexOf("__", index + 2);
			if (end > index + 2 && !/\w/.test(text[index - 1] ?? " ") && !/\w/.test(text[end + 2] ?? " ")) {
				flush();
				runs.push(new Run(text.slice(index + 2, end), true, false, false));
				index = end + 1;
				continue;
			}
		}
		if (char === "*" && !/\w/.test(text[index - 1] ?? " ") && !/\s/.test(text[index + 1] ?? " ")) {
			const end = text.indexOf("*", index + 1);
			if (end > index + 1 && !/\s/.test(text[end - 1] ?? " ") && !/\w/.test(text[end + 1] ?? " ")) {
				flush();
				runs.push(new Run(text.slice(index + 1, end), false, true, false));
				index = end;
				continue;
			}
		}
		plain += char;
	}
	flush();
	return runs;
}

/** Join runs back to text, preserving emphasis markers where they existed. */
export function runsToMarkdown(runs) {
	let out = "";
	for (const run of runs) {
		if (run.code) out += `\`${run.text}\``;
		else if (run.bold) out += `**${run.text}**`;
		else if (run.italic) out += `*${run.text}*`;
		else out += run.text;
	}
	return out;
}

/** Parse Markdown into document blocks. Unknown blocks degrade to paragraphs. */
export function parseMarkdown(markdown) {
	const text = String(markdown ?? "").replace(/\r\n?/g, "\n");
	const lines = text.split("\n");
	const blocks = [];
	let paragraph = [];
	const flushParagraph = () => {
		if (paragraph.length === 0) return;
		const runs = [];
		paragraph.forEach((line, index) => {
			if (index > 0) runs.push(new Run(" "));
			runs.push(...parseInline(line));
		});
		blocks.push(new Block("paragraph", { runs }));
		paragraph = [];
	};

	for (let index = 0; index < lines.length; index++) {
		const line = lines[index];
		const trimmed = line.trim();

		if (trimmed.startsWith("```")) {
			flushParagraph();
			const code = [];
			index++;
			while (index < lines.length && !lines[index].trim().startsWith("```")) {
				code.push(lines[index]);
				index++;
			}
			blocks.push(new Block("code", { lines: code }));
			continue;
		}

		if (trimmed.length === 0) {
			flushParagraph();
			continue;
		}

		const heading = /^(#{1,6})\s+(.*)$/.exec(trimmed);
		if (heading !== null) {
			flushParagraph();
			blocks.push(new Block("heading", {
				level: Math.min(3, heading[1].length),
				runs: parseInline(heading[2].trim())
			}));
			continue;
		}

		if (trimmed.startsWith("|") && index + 1 < lines.length && isTableSeparator(lines[index + 1])) {
			flushParagraph();
			const rows = [splitTableRow(trimmed)];
			index += 2;
			while (index < lines.length && lines[index].trim().startsWith("|")) {
				rows.push(splitTableRow(lines[index]));
				index++;
			}
			index--;
			blocks.push(new Block("table", { rows }));
			continue;
		}

		const bullet = /^(\s*)[-*+]\s+(.*)$/.exec(line);
		if (bullet !== null) {
			flushParagraph();
			blocks.push(new Block("bullet", {
				level: Math.min(2, Math.floor(bullet[1].length / 2)),
				runs: parseInline(bullet[2].trim())
			}));
			continue;
		}

		const numbered = /^(\s*)\d+[.)]\s+(.*)$/.exec(line);
		if (numbered !== null) {
			flushParagraph();
			blocks.push(new Block("numbered", {
				level: Math.min(2, Math.floor(numbered[1].length / 2)),
				runs: parseInline(numbered[2].trim())
			}));
			continue;
		}

		const quote = /^>\s?(.*)$/.exec(line);
		if (quote !== null) {
			flushParagraph();
			blocks.push(new Block("paragraph", { runs: parseInline(quote[1].trim()), quote: true }));
			continue;
		}

		if (/^([-*_])\1{2,}\s*$/.test(trimmed)) {
			flushParagraph();
			blocks.push(new Block("rule"));
			continue;
		}

		paragraph.push(trimmed);
	}
	flushParagraph();
	return blocks;
}

/** A short human summary used by the tool result ("12 段 · 2 表"). */
export function summarizeBlocks(blocks) {
	let paragraphs = 0;
	let tables = 0;
	let headings = 0;
	let lists = 0;
	for (const block of blocks) {
		if (block.type === "table") tables++;
		else if (block.type === "heading") headings++;
		else if (block.type === "bullet" || block.type === "numbered") lists++;
		else paragraphs++;
	}
	return { paragraphs, tables, headings, lists };
}
